         {
             Assert.Contains(assignment, command, StringComparison.Ordinal);
         }

         var previousIndex = -1;
         foreach (var assignment in CrossRuntimeReviewRuntimes.EnvAssignments[runtime])
         {
             var index = command.IndexOf(assignment, StringComparison.Ordinal);
             Assert.True(index > previousIndex, assignment);
             previousIndex = index;
         }

         CrossRuntimeReviewInvocationTestHelpers.AssertNoDenyFlags(runtime, command);
         var tokens = CrossRuntimeReviewInvocationTestHelpers.ShellTokens(command);
         foreach (var token in tokens.Where(token => token.StartsWith('-')))
         {
             Assert.Contains(token, CrossRuntimeReviewRuntimes.AllowedFlags[runtime]);
